    std::string transaction_date;
    double transaction_amount;
    std::string customer_id;
    std::string product_id;
    std::string chat_text; //For NLP
};


// Function to load data from CSV
std::vector<Transaction> load_data(const std::string& filename) {
    std::vector<Transaction> data;
    std::ifstream file(filename);
    std::string line;
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return data;
    }

    while (std::getline(file, line)) {
        std::stringstream ss(line);
        Transaction transaction;
        // Assuming CSV format: transaction_date,transaction_amount,customer_id,product_id,chat_text
        if (ss >> transaction.transaction_date >> transaction.transaction_amount >> transaction.customer_id >> transaction.product_id >> transaction.chat_text) {
            data.push_back(transaction);
        }
    }
    file.close();
    return data;
}

// Data Cleaning Functions
std::vector<Transaction> clean_data(const std::vector<Transaction>& data) {
    std::vector<Transaction> cleaned_data = data;
    // Remove Duplicates
    std::sort(cleaned_data.begin(), cleaned_data.end(), [](const Transaction& a, const Transaction& b) {
        return a.transaction_date < b.transaction_date;
    });
    cleaned_data.erase(std::unique(cleaned_data.begin(), cleaned_data.end(), [](const Transaction& a, const Transaction& b) {
        return a.transaction_date == b.transaction_date && a.customer_id == b.customer_id && a.product_id == b.product_id;
    }), cleaned_data.end());

    // Handle Missing Values (Simple Imputation)
    for (auto& transaction : cleaned_data) {
        if (transaction.transaction_amount == 0.0) {
            transaction.transaction_amount = 0.0; // or calculate mean/median
        }
    }
    return cleaned_data;
}

// Business Analysis Functions
std::map<std::string, double> analyze_transaction_data(const std::vector<Transaction>& data) {
    std::map<std::string, double> results;
    for (const auto& transaction : data) {
        results[transaction.transaction_date] = transaction.transaction_amount;
    }
    return results;
}

// NLP Analysis (Simplified)
