    std::stringstream report;
    for (const auto& pair : daily_sales) {
        report << pair.first << ", " << pair.second << std::endl;
    }
    return report.str();
}

int main() {
    // 1. Load Data
    std::vector<Transaction> data = load_data(DATA_DIR + "/transactions.csv"); // Example filename

    // 2. Clean Data
    data = clean_data(data);

    // 3. Business Analysis
