        return a.transaction_date == b.transaction_date && a.customer_id == b.customer_id && a.product_id == b.product_id;
    }), cleaned_data.end());

    // Handle missing transaction amounts by setting them to 0
    for (auto& transaction : cleaned_data) {
        if (transaction.transaction_amount == 0.0) {
            transaction.transaction_amount = 0.0;  // or implement more sophisticated imputation
        }
    }
    return cleaned_data;
}

// Function to analyze transaction data
